from __future__ import annotations

from pydantic_ai import Agent, RunContext

from rasa.builder.copilot.agent_sdk.tools import file_operations
from rasa.builder.copilot.agent_sdk.tools.constants import (
    TOOL_GET_PROJECT_FILE,
    TOOL_LIST_PROJECT_FILES,
    TOOL_READ_PROJECT_FILES,
    TOOL_UPDATE_MULTIPLE_FILES,
    TOOL_WRITE_PROJECT_FILE,
)
from rasa.builder.copilot.mcp_server.models import (
    FileContentResponse,
    FileListResponse,
    ReadFilesResponse,
    UpdateFilesResponse,
    WriteFileResponse,
)
from rasa.builder.copilot.pydantic_ai.run_context import CopilotRunContext


def register_file_tools(agent: Agent[CopilotRunContext, str]) -> None:
    """Register native project file read/write tools on the agent.

    These are thin adapters over the existing agent-SDK file implementations.
    The in-process MCP server intentionally exposes no generic file read/write
    tools (external IDEs bring their own), so v2 registers them natively here.
    Successful writes flip ``ctx.deps.made_changes`` so the runtime knows a
    commit is due.
    """

    @agent.tool(
        name=TOOL_LIST_PROJECT_FILES,
        description="List all files in the bot project as a directory tree.",
    )
    async def list_project_files(
        ctx: RunContext[CopilotRunContext],
    ) -> FileListResponse:
        """List all files in the bot project as a directory tree."""
        return await file_operations.list_files(_project_path(ctx))

    @agent.tool(
        name=TOOL_READ_PROJECT_FILES,
        description="Read all bot project files with their complete contents.",
    )
    async def read_project_files(
        ctx: RunContext[CopilotRunContext],
        exclude_docs: bool = True,
        allowed_extensions: str = "yaml,yml,py,jinja,jinja2",
    ) -> ReadFilesResponse:
        """Read all bot project files with their complete contents."""
        return await file_operations.read_assistant_files(
            _project_path(ctx), exclude_docs, allowed_extensions
        )

    @agent.tool(
        name=TOOL_GET_PROJECT_FILE,
        description="Get the content of a specific file in the bot project.",
    )
    async def get_project_file(
        ctx: RunContext[CopilotRunContext],
        file_path: str,
    ) -> FileContentResponse:
        """Get the content of a specific file in the bot project."""
        return await file_operations.get_file_content(_project_path(ctx), file_path)

    @agent.tool(
        name=TOOL_WRITE_PROJECT_FILE,
        description="Write or overwrite a file in the bot project.",
    )
    async def write_project_file(
        ctx: RunContext[CopilotRunContext],
        file_path: str,
        content: str,
    ) -> WriteFileResponse:
        """Write or overwrite a file in the bot project."""
        result = await file_operations.write_file(
            _project_path(ctx), file_path, content
        )
        if result.success:
            ctx.deps.made_changes = True
        return result

    @agent.tool(
        name=TOOL_UPDATE_MULTIPLE_FILES,
        description="Write multiple files in a single coordinated operation.",
    )
    async def update_multiple_files(
        ctx: RunContext[CopilotRunContext],
        files: dict[str, str],
    ) -> UpdateFilesResponse:
        """Write multiple files in a single coordinated operation."""
        result = await file_operations.update_files(_project_path(ctx), files)
        if result.updated:
            ctx.deps.made_changes = True
        return result


def _project_path(ctx: RunContext[CopilotRunContext]) -> str:
    """Return the current run's server-resolved project path.

    The web layer always injects the project path, so this is only ``None`` for a
    misconfigured run; raising makes that surface as a clear ``RUN_ERROR`` instead
    of silently operating on the wrong directory.
    """
    project_path = ctx.deps.project_path
    if project_path is None:
        raise RuntimeError("Copilot v2 run is missing a project path.")
    return project_path
